   873  static inline char *has_crlfcrlf(struct lwan_value *buffer)
   874  {
   875      return memmem(buffer->value, buffer->len, "\r\n\r\n", 4);
   876  }
   877
   878  static enum lwan_read_finalizer
   879  read_request_finalizer(size_t total_read,
   880                         size_t buffer_size,
   881                         struct lwan_request *request,
   882                         int n_packets)
   883  {
   884      struct lwan_request_parser_helper *helper = request->helper;
   885
   886      /* 16 packets should be enough to read a request (without the body, as
   887       * is the case for POST requests).  This yields a timeout error to avoid
   888       * clients being intentionally slow and hogging the server.  */
   889      if (UNLIKELY(n_packets > helper->error_when_n_packets))
   890          return FINALIZER_ERROR_TIMEOUT;
   891
   892      if (UNLIKELY(total_read < 4))
   893          return FINALIZER_YIELD_TRY_AGAIN;
   894
   895      char *crlfcrlf = has_crlfcrlf(helper->buffer);
   896      if (LIKELY(crlfcrlf)) {
   897          if (LIKELY(helper->next_request)) {
   898              helper->next_request = NULL;
   899              return FINALIZER_DONE;
   900          }
   901
   902          if (crlfcrlf != helper->buffer->value)
   903              return FINALIZER_DONE;
   904
   905          if (total_read > 16 && request->flags & REQUEST_ALLOW_PROXY_REQS) {
   906              /* FIXME: Checking for PROXYv2 protocol header here is a layering
   907               * violation. */
   908              STRING_SWITCH_LARGE (crlfcrlf + 4) {
   909              case MULTICHAR_CONSTANT_LARGE(0x00, 0x0d, 0x0a, 0x51, 0x55, 0x49,
   910                                            0x54, 0x0a):
   911                  return FINALIZER_DONE;
   912              }
   913          }
   914      }
   915
   916      if (UNLIKELY(total_read == buffer_size - 1))
   917          return FINALIZER_ERROR_TOO_LARGE;
   918
   919      return FINALIZER_TRY_AGAIN;
   920  }
